'use strict';

const { roundCurrency } = require('./format');

// Discount codes (exact, case-sensitive). See SPEC-T3.md.
//
//   SAVE10   10% off the parcel subtotal before tax, capped at 50.00 USD.
//            Tax is then charged on the discounted subtotal.
//   FREESHIP shipping is zeroed; the discount amount shown is the zone's
//            normal shipping price. Subtotal and tax are unaffected.
const SAVE10_RATE = 0.1;
const SAVE10_CAP_USD = 50;

const CODES = new Set(['SAVE10', 'FREESHIP']);

class UnknownDiscountCodeError extends Error {
  constructor(code) {
    super('unknown discount code: ' + code);
    this.name = 'UnknownDiscountCodeError';
    this.discountCode = code;
  }
}

function isRecognizedCode(code) {
  return typeof code === 'string' && CODES.has(code);
}

// applyDiscount(code, subtotalUsd, shippingUsd) -> {
//   discountUsd,   // amount shown on the DISCOUNT line
//   shippingUsd,   // possibly zeroed (FREESHIP)
//   taxableUsd,    // subtotal the tax is computed on
// }
function applyDiscount(code, subtotalUsd, shippingUsd) {
  if (!isRecognizedCode(code)) {
    throw new UnknownDiscountCodeError(code);
  }

  if (code === 'SAVE10') {
    const discountUsd = Math.min(roundCurrency(SAVE10_RATE * subtotalUsd), SAVE10_CAP_USD);
    return {
      discountUsd,
      shippingUsd,
      taxableUsd: roundCurrency(subtotalUsd - discountUsd),
    };
  }

  // FREESHIP
  return {
    discountUsd: shippingUsd,
    shippingUsd: 0,
    taxableUsd: subtotalUsd,
  };
}

module.exports = { isRecognizedCode, applyDiscount, UnknownDiscountCodeError };

