'use strict';

const { isRecognizedCode, applyDiscount, UnknownDiscountCodeError } = require('../lib/discount');

module.exports = function ({ assertEqual, assertThrows }) {
  assertEqual(isRecognizedCode('SAVE10'), true, 'SAVE10 is recognized');
  assertEqual(isRecognizedCode('FREESHIP'), true, 'FREESHIP is recognized');
  assertEqual(isRecognizedCode('save10'), false, 'codes are case-sensitive');
  assertEqual(isRecognizedCode(''), false, 'empty string is not recognized');
  assertEqual(isRecognizedCode('BOGUS'), false, 'an unknown word is not recognized');

  const save10 = applyDiscount('SAVE10', 23, 4.5);
  assertEqual(save10.discountUsd, 2.3, 'SAVE10 discount is 10% of subtotal');
  assertEqual(save10.shippingUsd, 4.5, 'SAVE10 leaves shipping unchanged');
  assertEqual(save10.taxableUsd, 20.7, 'SAVE10 taxable amount is subtotal minus discount');

  const capped = applyDiscount('SAVE10', 800, 4.5);
  assertEqual(capped.discountUsd, 50, 'SAVE10 discount is capped at 50.00 USD');
  assertEqual(capped.taxableUsd, 750, 'SAVE10 taxable amount reflects the capped discount');

  const freeship = applyDiscount('FREESHIP', 41, 22);
  assertEqual(freeship.discountUsd, 22, 'FREESHIP discount equals the zone shipping price');
  assertEqual(freeship.shippingUsd, 0, 'FREESHIP zeroes the shipping charge');
  assertEqual(freeship.taxableUsd, 41, 'FREESHIP does not affect the taxable subtotal');

  assertThrows(() => applyDiscount('BOGUS', 23, 4.5), 'an unrecognized code throws');

  try {
    applyDiscount('BOGUS', 23, 4.5);
  } catch (e) {
    assertEqual(e instanceof UnknownDiscountCodeError, true, 'the thrown error is an UnknownDiscountCodeError');
    assertEqual(e.discountCode, 'BOGUS', 'the error carries the raw code value');
  }
};

